document.addEventListener('DOMContentLoaded',()=>{if(!location.pathname.endsWith('/customer_view.php'))return;const root=document.querySelector('.content');if(!root)return;const enhance=()=>{root.querySelectorAll('.customer-advance-section tbody tr').forEach(row=>{if(row.querySelector('.apply-customer-advance'))return;const receipt=[...row.querySelectorAll('a')].find(link=>link.href.includes('/advance_receipt.php?id='));if(!receipt)return;const id=new URL(receipt.href).searchParams.get('id'),cells=row.querySelectorAll('td'),amountMatch=(cells[6]?.textContent||'').match(/[0-9][0-9,]*(?:\.[0-9]+)?/),available=amountMatch?Number(amountMatch[0].replaceAll(',','')):0,status=(cells[7]?.textContent||'').trim().toLowerCase().replaceAll('_',' ');if(available<=0||!['open','partially applied'].includes(status))return;const apply=document.createElement('a');apply.className='btn primary apply-customer-advance';apply.href='advances.php?apply_advance='+encodeURIComponent(id);apply.textContent='Apply to Invoice';receipt.insertAdjacentElement('afterend',apply)})};const observer=new MutationObserver(enhance);observer.observe(root,{childList:true,subtree:true});enhance();let checks=0;const timer=setInterval(()=>{enhance();if(++checks>=10||root.querySelector('.apply-customer-advance'))clearInterval(timer)},300)});
