document.addEventListener('click',event=>{const button=event.target.closest('.product-details-button');if(!button)return;const edit=button.closest('tr')?.querySelector('a[href^="edit_record.php?type=product&id="]'),id=edit?new URL(edit.href).searchParams.get('id'):'';if(!id)return;setTimeout(()=>{const box=document.querySelector('.product-details-modal [data-product-details]');if(!box||box.querySelector('.product-advance-summary'))return;fetch('product_details.php?id='+encodeURIComponent(id),{credentials:'same-origin'}).then(response=>response.json()).then(data=>{const p=data.product,a=p?.advance_summary;if(!a||Number(a.requested_quantity)<=0||box.querySelector('.product-advance-summary'))return;const money=value=>'Rs. '+Number(value||0).toLocaleString('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2}),qty=value=>Number(value||0).toLocaleString('en-LK',{maximumFractionDigits:3});const section=document.createElement('section');section.className='product-advance-summary';section.innerHTML='<div class="product-sales-heading"><span class="eyebrow">Advance customer orders</span><h3>Requested units from advance payments</h3><p>These units are reserved by customers but are not sold until final invoices are created.</p></div><div class="product-advance-cards"><article><span>Requested Units</span><strong>'+qty(a.requested_quantity)+' '+p.unit+'</strong><small>'+qty(a.open_advance_orders)+' open advance order(s)</small></article><article><span>Current Stock</span><strong>'+qty(a.current_stock)+' '+p.unit+'</strong><small>Physical stock currently available</small></article><article class="'+(Number(a.units_waiting)>0?'advance-shortage':'advance-ready')+'"><span>'+(Number(a.units_waiting)>0?'Still Need Stock':'Stock Ready')+'</span><strong>'+(Number(a.units_waiting)>0?qty(a.units_waiting)+' '+p.unit:'Ready to invoice')+'</strong><small>'+(Number(a.units_waiting)>0?'Additional units required for advance orders':'Enough stock for current advance requests')+'</small></article><article><span>Expected Order Value</span><strong>'+money(a.expected_order_value)+'</strong><small>Expected final invoice value</small></article><article><span>Advance Received</span><strong>'+money(a.advance_received)+'</strong><small>Customer money received for this product</small></article><article><span>Advance Available</span><strong>'+money(a.advance_available)+'</strong><small>Not yet applied to final invoices</small></article></div><a class="btn secondary wide" href="advances.php">View Advance Orders</a>';const sales=box.querySelector('.product-sales-summary'),actions=box.querySelector('.product-detail-actions');if(sales)sales.after(section);else if(actions)actions.before(section);else box.appendChild(section)}).catch(()=>{})},550)});
document.addEventListener('DOMContentLoaded',()=>{if(!location.pathname.endsWith('/sale.php')||!document.querySelector('#sale-form'))return;const customer=document.querySelector('#customer-select'),paid=document.querySelector('#paid'),balance=document.querySelector('#balance'),total=document.querySelector('#total');if(!customer||!paid||!balance||!total)return;const block=document.createElement('div');block.className='sale-future-money';block.hidden=true;block.innerHTML='<div><span>Customer extra money for future purchases</span><strong data-future-available>Rs. 0.00</strong></div><label>Use on this purchase<input type="number" name="future_money_amount" value="0" min="0" step="0.01"></label><small>This uses only extra money. Money reserved for existing advance orders remains protected.</small>';paid.closest('label')?.after(block);const input=block.querySelector('input'),availableText=block.querySelector('[data-future-available]'),money=value=>'Rs. '+Number(value||0).toLocaleString('en-LK',{minimumFractionDigits:2,maximumFractionDigits:2});let available=0;const refreshBalance=()=>{const amountMatch=(total.textContent||'').match(/[0-9][0-9,]*(?:\.[0-9]+)?/),invoice=amountMatch?Number(amountMatch[0].replaceAll(',','')):0,use=Math.min(available,Math.max(0,Number(input.value||0)),invoice),cash=Math.max(0,Number(paid.value||0));if(Number(input.value||0)!==use)input.value=use.toFixed(2);balance.textContent=money(Math.max(0,invoice-cash-use));block.classList.toggle('future-covers-all',use>=invoice&&invoice>0)};const load=async()=>{available=0;input.value='0';const id=customer.value;if(!id){block.hidden=true;refreshBalance();return}try{const response=await fetch('customer_advance_balances.php',{credentials:'same-origin'}),data=await response.json();available=Number(data.balances?.[id]?.extra_for_future||0);availableText.textContent=money(available);input.max=available.toFixed(2);block.hidden=available<=0}catch(error){block.hidden=true}refreshBalance()};customer.addEventListener('change',load);input.addEventListener('input',refreshBalance);paid.addEventListener('input',()=>setTimeout(refreshBalance,0));new MutationObserver(refreshBalance).observe(total,{childList:true,characterData:true,subtree:true});load()});

document.addEventListener('DOMContentLoaded',()=>{if(!location.pathname.endsWith('/sale.php'))return;const form=document.querySelector('#sale-form'),paid=document.querySelector('#paid'),method=form?.querySelector('select[name="payment_method"]'),total=document.querySelector('#total');if(!form||!paid||!method||!total)return;const hidden=document.createElement('input');hidden.type='hidden';hidden.name='payment_method';hidden.disabled=true;form.appendChild(hidden);const update=()=>{const future=form.querySelector('[name="future_money_amount"]'),match=(total.textContent||'').match(/[0-9][0-9,]*(?:\.[0-9]+)?/),invoice=match?Number(match[0].replaceAll(',','')):0,use=Number(future?.value||0),covered=invoice>0&&use>=invoice-.005;paid.readOnly=covered;paid.closest('label')?.classList.toggle('payment-disabled',covered);method.disabled=covered;method.closest('label')?.classList.toggle('payment-disabled',covered);hidden.disabled=!covered;hidden.value='customer_advance';if(covered)paid.value='0';const label=method.closest('label'),wanted=covered?'Payment method (not needed)':'Method';if(label?.childNodes[0]?.textContent!==wanted)label.childNodes[0].textContent=wanted;const message=form.querySelector('.advance-paid-message')||document.createElement('div');message.className='advance-paid-message';if(!message.textContent)message.textContent='Paid fully using customer future money — no new cash or payment method is needed.';message.hidden=!covered;if(!message.isConnected)method.closest('label')?.before(message)};form.addEventListener('input',event=>{if(event.target.matches('[name="future_money_amount"],#paid,#discount,.qty,.disc,.unit-price'))setTimeout(update,0)});new MutationObserver(update).observe(total,{childList:true,subtree:true,characterData:true});setTimeout(update,100)});

document.addEventListener('DOMContentLoaded',()=>{if(!location.pathname.endsWith('/sale_view.php'))return;const definitions=[['a[href^="edit_record.php?type=sale&id="]','✎','Correct invoice details'],['a[href^="customer_view.php?id="]','👤','View customer account'],['a[href^="edit_record.php?type=customer_payment&id="]','✎','Correct receipt details'],['a[href^="payment_document.php?type=customer&id="]','⎙','Print receipt'],['a[href^="customer_payment_reverse.php?id="]','↩','Cash or cheque return']];const enhance=()=>definitions.forEach(([selector,icon,label])=>document.querySelectorAll(selector).forEach(link=>{if(link.dataset.iconAction)return;link.dataset.iconAction='1';link.classList.add('invoice-icon-action');link.title=label;link.setAttribute('aria-label',label);link.innerHTML='<span class="action-symbol" aria-hidden="true">'+icon+'</span><span class="action-label">'+label+'</span>'}));enhance();new MutationObserver(enhance).observe(document.body,{childList:true,subtree:true})});
